#include <assert.h>
#include <stdio.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include "../../main/audio/ap2_buffered_fifo.c"
int socket_utils_bind_tcp_listener(uint16_t port,int backlog,bool nonblock,uint16_t*out){int fd=socket(AF_INET,SOCK_STREAM,0);assert(fd>=0);struct sockaddr_in a={.sin_family=AF_INET,.sin_addr.s_addr=htonl(INADDR_LOOPBACK),.sin_port=htons(port)};assert(bind(fd,(void*)&a,sizeof(a))==0);socklen_t n=sizeof(a);assert(getsockname(fd,(void*)&a,&n)==0);assert(listen(fd,backlog)==0);if(nonblock)fcntl(fd,F_SETFL,O_NONBLOCK);*out=ntohs(a.sin_port);return fd;}
static void run(bool partial){uint8_t storage[16384];ap2_buffered_fifo_t*f;ap2_buffered_fifo_config_t cfg={16384,0,4,4096};assert(ap2_buffered_fifo_create_with_storage(&f,&cfg,storage,sizeof(storage))==ESP_OK);uint16_t port;assert(ap2_buffered_fifo_start(f,0,&port)==ESP_OK);int c=socket(AF_INET,SOCK_STREAM,0);struct sockaddr_in a={.sin_family=AF_INET,.sin_addr.s_addr=htonl(INADDR_LOOPBACK),.sin_port=htons(port)};assert(connect(c,(void*)&a,sizeof(a))==0);
uint8_t packet[15]={0,14};assert(send(c,packet,partial?15:14,0)==(partial?15:14));shutdown(c,SHUT_WR);
for(int i=0;i<200&&!ap2_buffered_fifo_eof_pending(f);i++)vTaskDelay(10);assert(ap2_buffered_fifo_eof_pending(f));
ap2_buffered_fifo_head_t h;assert(ap2_buffered_fifo_peek_head(f,8192,&h)==ESP_OK);uint32_t epoch=h.stream_epoch;assert(h.wire_len==14);uint8_t out[8192];assert(ap2_buffered_fifo_read_head(f,&h,out,sizeof(out))==ESP_OK);assert(ap2_buffered_fifo_peek_head(f,8192,&h)==ESP_ERR_TIMEOUT);assert(ap2_buffered_fifo_eof_pending(f));assert(ap2_buffered_fifo_epoch_is_current(f,epoch));
ap2_buffered_fifo_ack_eof(f);assert(!ap2_buffered_fifo_eof_pending(f));ap2_buffered_fifo_usage_t used;ap2_buffered_fifo_get_usage(f,&used);assert(used.used_bytes==0);close(c);ap2_buffered_fifo_stop(f);assert(ap2_buffered_fifo_destroy(f)==ESP_OK);}
static void reconnect(void){uint8_t storage[16384];ap2_buffered_fifo_t*f;ap2_buffered_fifo_config_t cfg={16384,0,4,4096};assert(ap2_buffered_fifo_create_with_storage(&f,&cfg,storage,sizeof(storage))==ESP_OK);uint16_t port;assert(ap2_buffered_fifo_start(f,0,&port)==ESP_OK);struct sockaddr_in a={.sin_family=AF_INET,.sin_addr.s_addr=htonl(INADDR_LOOPBACK),.sin_port=htons(port)};uint8_t packet[14]={0,14,0,0,0,1};int c1=socket(AF_INET,SOCK_STREAM,0);assert(connect(c1,(void*)&a,sizeof(a))==0);assert(send(c1,packet,14,0)==14);shutdown(c1,SHUT_WR);for(int i=0;i<200&&!ap2_buffered_fifo_eof_pending(f);i++)vTaskDelay(10);assert(ap2_buffered_fifo_eof_pending(f));ap2_buffered_fifo_head_t old,h;assert(ap2_buffered_fifo_peek_head(f,8192,&old)==ESP_OK);int c2=socket(AF_INET,SOCK_STREAM,0);assert(connect(c2,(void*)&a,sizeof(a))==0);packet[5]=2;assert(send(c2,packet,14,0)==14);shutdown(c2,SHUT_WR);bool replaced=false;for(int i=0;i<200;i++){if(ap2_buffered_fifo_peek_head(f,8192,&h)==ESP_OK&&h.stream_epoch!=old.stream_epoch&&h.header[3]==2&&ap2_buffered_fifo_eof_pending(f)){replaced=true;break;}vTaskDelay(10);}assert(replaced);uint8_t out[8192];assert(ap2_buffered_fifo_read_head(f,&h,out,sizeof(out))==ESP_OK);ap2_buffered_fifo_ack_eof(f);close(c1);close(c2);ap2_buffered_fifo_stop(f);assert(ap2_buffered_fifo_destroy(f)==ESP_OK);puts("PASS replacement TCP connection supersedes FIN queue without waiting for paused/old AUs");}
int main(void){run(false);run(true);reconnect();puts("PASS real TCP EOF preserves final complete packets and epoch until drain; partial tail is discarded on acknowledgment");}
